test('현재 주체·등록·factory·scope 변조는 원 지원 자료를 반환하지 않는다',async()=>{for(const mode of ['SESSION_REVOKED','CREDENTIAL_CHANGED','CONTROL_CHANGED','KEY_CHANGED','REG_REVOKED','BASIS_CHANGED','WRONG_FACTORY','WRONG_SCOPE']){const f=await currentFixture();try{f.mode(mode);const r=await f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});assert.ok([401,409,503].includes(r.statusCode),mode+': '+r.body);assert.match(r.json().code,/^NATIVE_/);assert.equal(r.json().items,undefined);}finally{await f.close();}}});

test('원 command·audit·head·bootstrap의 결손은 mapping 전에 거절한다',async()=>{const cases:[string,(data:any)=>void][]=[['audit',data=>{data.audits=[];}],['command hash',data=>{data.commands[0].request_hash='f'.repeat(64);}],['head hash',data=>{data.heads[0].content_hash='f'.repeat(64);}],['bootstrap absent',data=>{data.events=[];data.heads=[];}],['observation absent',data=>{const index=data.events.findIndex((e:any)=>e.kind==='BOUNDARY_OBSERVATION_ACCEPTED');assert.ok(index>=0);data.events.splice(index,1);}]];for(const [name,change] of cases){const f=await currentFixture();try{f.mutate(change);const r=await f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});assert.equal(r.statusCode,503,name+': '+r.body);assert.equal(f.mappingCalls(),0);}finally{await f.close();}}});

test('명시 mapping 부재는 정상 원장 조회 뒤에도 빈 성공을 만들지 않는다',async()=>{const f=await currentFixture(false,false);try{const r=await f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});assert.equal(r.statusCode,503,r.body);assert.equal(f.mappingCalls(),0);assert.ok(f.calls.some(s=>s.includes('project_writer_authority_events')));}finally{await f.close();}});

test('기존 공개 등록 reader는 STATUS_ONLY 사실과 원 권한을 유지한다',async()=>{const f=await currentFixture();try{const reader=new ProjectRegistrationReads(f.config.installationId),r=await reader.read(f.db as unknown as PoolClient,f.actor as any,f.pid,f.config.registrationRef.id);assert.equal(r.credential.status,'ACTIVE_STATUS_ONLY');assert.equal(r.scope.credentialScope,'REGISTRATION_STATUS_ONLY');assert.equal(r.executionAuthorized,false);assert.deepEqual(r.grants,[]);f.deny();await assert.rejects(()=>reader.read(f.db as unknown as PoolClient,f.actor as any,f.pid,f.config.registrationRef.id),(error:unknown)=>error instanceof AuthFailure&&error.statusCode===403);const denied=await f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});assert.equal(denied.statusCode,403,denied.body);assert.equal(f.mappingCalls(),0);}finally{await f.close();}});

test('native 읽기에 새 재인증을 붙이지 않고 원 prepare 재인증은 유지한다',async()=>{const f=await currentFixture();try{f.mode('NO_REAUTH');Reflect.set(f.actor,'reauthUntil',null);const r=await f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});assert.equal(r.statusCode,200,r.body+f.error());await assert.rejects(()=>f.service.command('model-session','c'.repeat(43),f.nativeCommand),(error:unknown)=>error instanceof AuthFailure&&error.message==='REAUTHENTICATION_REQUIRED');assert.equal(f.data().native.length,0);}finally{await f.close();}});
test('mapping 결과의 getter는 실행 없이 거절한다',async()=>{const f=await currentFixture();try{f.mode('ITEM_GETTER');const r=await f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});assert.equal(r.statusCode,503,r.body);assert.equal(f.hints.getterReads??0,0);}finally{await f.close();}});

test('binding getter는 생성과 현재 재검산에서 실행 없이 거절한다',async()=>{const f=await currentFixture();try{let createdReads=0;const mapping={...f.mapping,binding:{...f.mapping.binding}};Object.defineProperty(mapping.binding,'projectId',{get:()=>{createdReads++;return f.pid;},enumerable:true});assert.throws(()=>new NativePreparationCurrentSource({installationId:f.config.installationId,writer:f.persistence,catalogue:f.catalogue,mapping,crypto:{allocate:f.nativeSource.allocate,credential:f.nativeSource.credential}}));assert.equal(createdReads,0);let liveReads=0;Object.defineProperty(f.mapping.binding,'projectId',{get:()=>{liveReads++;return f.pid;},enumerable:true});const r=await f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});assert.equal(r.statusCode,503,r.body);assert.equal(liveReads,0);}finally{await f.close();}});

test('mapping await 뒤 함수 교체는 늦은 결과와 추가 query를 닫는다',async()=>{const f=await currentFixture();f.mode('HOLD');const work=f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});let released=false;try{await Promise.race([f.mappingEntered,work.then(()=>{throw Error('MAPPING_NOT_ENTERED');})]);const count=f.calls.length;Reflect.defineProperty(f.mapping,'read',{value:async()=>[]});f.release(f.hints.mappingValue);released=true;const r=await work;assert.equal(r.statusCode,503,r.body);assert.equal(f.calls.length,count);await new Promise<void>(resolve=>setImmediate(resolve));assert.equal(f.service.pendingOptionsSuppliers,0);}finally{if(!released&&f.hints.mappingValue)f.release(f.hints.mappingValue);await work;await f.close();}});

test('원 options timeout 뒤 mapping이 정착해도 query와 성공을 재개하지 않는다',async()=>{const f=await currentFixture(false,true,500);f.mode('HOLD');const work=f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});let released=false;try{await Promise.race([f.mappingEntered,work.then(()=>{throw Error('MAPPING_NOT_ENTERED');})]);const r=await work;assert.equal(r.statusCode,412,r.body);assert.equal((f.hints.lease as {signal:AbortSignal}).signal.aborted,true);const count=f.calls.length;f.release(f.hints.mappingValue);released=true;await new Promise<void>(resolve=>setImmediate(resolve));assert.equal(f.calls.length,count);assert.equal(f.service.pendingOptionsSuppliers,0);assert.equal(f.service.pendingOptionsTransactions,0);}finally{if(!released&&f.hints.mappingValue)f.release(f.hints.mappingValue);await work;await f.close();}});

test('mapping 보류 중 현재 session 회수는 재조회 후 실패로 남긴다',async()=>{const f=await currentFixture();f.mode('HOLD');const work=f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});let released=false;try{await Promise.race([f.mappingEntered,work.then(()=>{throw Error('MAPPING_NOT_ENTERED');})]);f.mode('SESSION_REVOKED');f.release(f.hints.mappingValue);released=true;const r=await work;assert.equal(r.statusCode,401,r.body);assert.equal(f.data().native.length,0);}finally{if(!released&&f.hints.mappingValue)f.release(f.hints.mappingValue);await work;await f.close();}});
test('정책 조회에 소비한 시간도 원 mapping 잔여 예산에서 빠진다',async()=>{const f=await currentFixture(false,true,1000);try{f.mode('DELAY_POLICY');const r=await f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});assert.equal(r.statusCode,200,r.body+f.error());assert.ok(typeof f.hints.remaining==='number'&&f.hints.remaining>0&&f.hints.remaining<=950,String(f.hints.remaining));}finally{await f.close();}});

test('다른 prepare 명령으로 원 RESERVED current를 재사용하지 않는다',async()=>{const f=await currentFixture();try{await f.service.command('model-session','c'.repeat(43),f.nativeCommand);const authority=f.data().native[0];f.mode('OTHER_COMMAND');const r=await f.nativeApp.inject({method:'GET',url:'/api/v1/connector/native-preparations/'+authority.id+'/current',headers:{host:new URL(f.origin).host,authorization:'Bearer '+testOpaque}});assert.equal(r.statusCode,409,r.body);assert.equal(r.json().code,'NATIVE_CONTEXT_CHANGED');assert.equal(f.data().native.length,1);assert.equal(f.data().heads[0].phase,'RESERVED');}finally{await f.close();}});
test('일회 승인 소비 뒤 원 current 재조회는 역사 proof만 복원하고 다시 소비하지 않는다',async()=>{const f=await currentFixture(true);try{const result=await f.service.command('model-session','c'.repeat(43),f.nativeCommand).catch((error:Error)=>{throw Error(error.message+': '+JSON.stringify(f.hints.currentTimes));});assert.ok(result&&typeof result==='object');assert.equal((result as {status:string}).status,'APPLIED');const before=f.approvals();assert.ok(before);const authority=f.data().native[0];for(let i=0;i<2;i++){const r=await f.nativeApp.inject({method:'GET',url:'/api/v1/connector/native-preparations/'+authority.id+'/current',headers:{host:new URL(f.origin).host,authorization:'Bearer '+testOpaque}});assert.equal(r.statusCode,200,r.body);assert.equal(r.json().phase,'RESERVED');}assert.deepEqual(f.approvals(),before);assert.equal(f.data().native.length,1);}finally{await f.close();}});
test('예약 후 current 기한 확대나 발급 권위보다 이른 소진은 원 transaction을 되돌린다',async()=>{for(const mode of ['AFTER_WIDEN','AFTER_SHRINK']){const f=await currentFixture();try{f.mode(mode);await assert.rejects(()=>f.service.command('model-session','c'.repeat(43),f.nativeCommand),(error:unknown)=>error instanceof AuthFailure&&error.message==='NATIVE_CONTEXT_CHANGED');assert.equal(f.data().native.length,0);assert.equal(f.data().heads[0].phase,'EMPTY_AT');}finally{await f.close();}}});
test('writer 원장 조회 중 원 head가 만료되면 mapping을 시작하지 않는다',async()=>{const f=await currentFixture();try{f.mode('WRITER_EXPIRED');const r=await f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});assert.notEqual(r.statusCode,200,r.body);assert.equal(f.mappingCalls(),0);assert.equal(f.data().native.length,0);}finally{await f.close();}});
test('정책 조회가 세션 최소기한을 넘기면 원 시각의 잔여 시간을 다시 더하지 않는다',async()=>{const f=await currentFixture();try{f.mode('AUTH_EXPIRED');const r=await f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});assert.notEqual(r.statusCode,200,r.body);assert.equal(f.mappingCalls(),0);assert.equal(f.data().native.length,0);}finally{await f.close();}});
test('등록 조회 중 mapping 최소기한이 소진되면 후속 query를 시작하지 않는다',async()=>{const f=await currentFixture();try{f.mode('ITEM_EXPIRED');const r=await f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});assert.notEqual(r.statusCode,200,r.body);assert.equal(f.hints.lateQueries??0,0);assert.equal(f.data().native.length,0);}finally{await f.close();}});
test('후행 DB 시각 전진 뒤 mapping 최소기한도 같은 관측 anchor를 사용한다',async()=>{const f=await currentFixture();try{f.mode('ITEM_DB_FORWARD');const r=await f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});assert.notEqual(r.statusCode,200,r.body);assert.equal(f.hints.lateQueries??0,0);assert.equal(f.data().native.length,0);}finally{await f.close();}});
test('DB 전진 뒤 mapping HOLD 동안 지난 item 기한은 후속 query 전에 차감한다',async()=>{
 const f=await currentFixture();f.mode('HOLD_DB_FORWARD');let released=false,afterRelease=false,lateQueries=0;const query=f.db.query.bind(f.db);f.db.query=async(sql:string,args:any[]=[])=>{if(afterRelease)lateQueries++;return query(sql,args);};
 const work=f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});
 try{await Promise.race([f.mappingEntered,work.then(()=>{throw Error('MAPPING_NOT_ENTERED');})]);await new Promise<void>(resolve=>setTimeout(resolve,150));afterRelease=true;f.release(f.hints.mappingValue);released=true;const r=await work;assert.notEqual(r.statusCode,200,r.body);assert.equal(lateQueries,0);assert.equal(f.data().native.length,0);}
 finally{if(!released&&f.hints.mappingValue)f.release(f.hints.mappingValue);await work;await f.close();}
});
test('private clock 전진은 공개 observedAt의 실제 auth DB 관측을 덮지 않는다',async()=>{
 const f=await currentFixture();f.mode('ROOT_DB_FORWARD');let sessionRead=false;const observed:string[]=[],query=f.db.query.bind(f.db);f.db.query=async(sql:string,args:any[]=[])=>{if(sql.startsWith('SELECT s.*,u.status AS user_status'))sessionRead=true;const result=await query(sql,args);if(sessionRead&&sql==='SELECT clock_timestamp() AS at'){sessionRead=false;observed.push(result.rows[0].at.toISOString());}return result;};
 try{const r=await f.nativeApp.inject({method:'GET',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparation-options',headers:f.headers});assert.equal(r.statusCode,200,r.body+f.error());assert.ok(observed.length>=3);assert.equal(r.json().observedAt,observed.at(-1));assert.ok(Date.parse(r.json().observedAt)>=Date.parse(observed[0]!)+1000);assert.equal(f.mappingCalls(),1);}finally{await f.close();}
});
